/* Modal de confirmación de borrado (SRCH-03). Solo tokens `--bw-*` como color. */

.overlay {
  position: fixed;
  inset: 0;
  z-index: 200;
  display: flex;
  align-items: center;
  justify-content: center;
  background: var(--bw-sidebar-overlay);
}

.dialog {
  width: 420px;
  max-width: 90vw;
  padding: 28px;
  background: var(--bw-warm-cream);
  border: 1px solid var(--bw-line-steel);
  border-radius: 8px;
  box-shadow: 0 20px 60px var(--bw-sidebar-overlay);
}

.icon {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 42px;
  height: 42px;
  margin-bottom: 14px;
  font-size: 20px;
  color: var(--bw-sensitive-text);
  background: var(--bw-sensitive-bg);
  border: 1px solid var(--bw-badge-danger-border);
  border-radius: 50%;
}

.title {
  font-family: var(--bw-font-title);
  font-size: 16px;
  font-weight: 700;
  line-height: 1.5;
  color: var(--bw-deep-steel);
  margin: 0 0 16px;
}

.error {
  font-family: var(--bw-font-body);
  font-size: var(--bw-size-input);
  color: var(--bw-error-text);
  background: var(--bw-sensitive-bg);
  border: 1px solid var(--bw-badge-danger-border);
  border-radius: var(--bw-radius);
  padding: 8px 12px;
  margin: 0 0 16px;
}

.buttons {
  display: flex;
  justify-content: flex-end;
  gap: 10px;
}

.cancel {
  padding: 8px 18px;
  font-family: var(--bw-font-body);
  font-size: var(--bw-size-input);
  font-weight: 500;
  color: var(--bw-ink-steel);
  background: var(--bw-cold-white);
  border: 1px solid var(--bw-line-steel-strong);
  border-radius: var(--bw-radius);
  cursor: pointer;
  transition: border-color 0.12s;
}

.cancel:hover {
  border-color: var(--bw-hover-border);
}

.confirm {
  padding: 8px 18px;
  font-family: var(--bw-font-body);
  font-size: var(--bw-size-input);
  font-weight: 500;
  color: var(--bw-cold-white);
  background: var(--bw-sensitive-text);
  border: none;
  border-radius: var(--bw-radius);
  cursor: pointer;
  transition: opacity 0.12s;
}

.confirm:hover {
  opacity: 0.87;
}

.confirm:disabled {
  opacity: 0.5;
  cursor: not-allowed;
}

import styles from './DeleteWatcherModal.module.css';

interface Props {
  partNumber: string;
  /** La llamada de borrado está en vuelo: el botón primario se apaga. */
  busy: boolean;
  /** Error del `deleteWatcher`; el modal sigue abierto con el mensaje dentro. */
  error: string | null;
  onConfirm: () => void;
  onCancel: () => void;
}

/** El id del título: el nombre accesible del diálogo sale de aquí. */
const TITLE_ID = 'delete-watcher-title';

/**
 * Confirmación del borrado (spec §6). Totalmente controlado y sin test propio: se
 * prueba entero a través de `Watchers.test.tsx`. No hay papelera ni recuperación,
 * así que `Eliminar` nunca se dispara sin pasar por aquí; y no se cierra con clic
 * fuera — solo con `Cancelar` (o con el borrado que sale bien, que lo cierra
 * arriba).
 */
export function DeleteWatcherModal({ partNumber, busy, error, onConfirm, onCancel }: Props) {
  return (
    <div className={styles.overlay} role="dialog" aria-modal="true" aria-labelledby={TITLE_ID}>
      <div className={styles.dialog}>
        <div className={styles.icon} aria-hidden="true">
          <i className="ti ti-trash" />
        </div>
        {/* El texto entero, en una sola expresión: el nombre accesible es exacto. */}
        <h2 id={TITLE_ID} className={styles.title}>
          {'¿Eliminar el watcher de ' + partNumber + '? Esta acción no se puede deshacer.'}
        </h2>

        {error !== null && (
          <p className={styles.error} role="alert">
            {error}
          </p>
        )}

        <div className={styles.buttons}>
          <button type="button" className={styles.cancel} onClick={onCancel}>
            Cancelar
          </button>
          <button type="button" className={styles.confirm} onClick={onConfirm} disabled={busy}>
            Eliminar
          </button>
        </div>
      </div>
    </div>
  );
}

