import {
  conditionsLabel,
  daysLeftLabel,
  daysTone,
  expiresInLabel,
  sinceLabel,
  triggeredLabel,
  type WatcherRow,
} from '../../lib/watchers';
import styles from './WatcherCard.module.css';

interface Props {
  row: WatcherRow;
  /** Inyectable: la tarjeta no mira el reloj por su cuenta. */
  now: Date;
  /** Hay una llamada en vuelo: TODOS los botones de la tarjeta van deshabilitados. */
  busy: boolean;
  onPause: (row: WatcherRow) => void;
  onResume: (row: WatcherRow) => void;
  onEdit: (row: WatcherRow) => void;
  onDelete: (row: WatcherRow) => void;
  onRenew: (row: WatcherRow) => void;
  onLetExpire: (row: WatcherRow) => void;
  onViewResults: (row: WatcherRow) => void;
}

/**
 * Tarjeta de un watcher. Presentacional: sin red y sin estado propio. Los botones
 * que se pintan dependen del estado de la fila; cada uno llama a su callback con la
 * fila ENTERA. El texto de la acción y su `aria-label` («Acción — referencia») se
 * construyen aquí, así que un test puede pulsar por nombre accesible.
 */
export function WatcherCard({
  row,
  now,
  busy,
  onPause,
  onResume,
  onEdit,
  onDelete,
  onRenew,
  onLetExpire,
  onViewResults,
}: Props) {
  // Días restantes solo en ACTIVE y PAUSED (spec §3).
  const showsDays = row.state === 'ACTIVE' || row.state === 'PAUSED';
  const days = row.daysRemaining ?? 0;
  const triggered = triggeredLabel(row);

  return (
    <article className={styles.card} aria-label={'Watcher ' + row.partNumber} data-state={row.state}>
      <div className={styles.top}>
        <span className={styles.ref}>{row.partNumber}</span>
        {/* El estado tal cual llega de la capa de datos, sin traducir. */}
        <span className={styles.badge} data-state={row.state}>
          {row.state}
        </span>
      </div>

      <p className={styles.conditions}>{conditionsLabel(row)}</p>
      <p className={styles.created}>{'Creado: ' + sinceLabel(row.createdAt, now)}</p>

      <div className={styles.channels}>
        {/* In-app SIEMPRE; email solo si el watcher lo tiene activado. */}
        <span className={styles.channel}>
          <i className={`ti ti-bell ${styles.icon}`} aria-hidden="true" />
          In-app
        </span>
        {row.emailChannel && (
          <span className={styles.channel}>
            <i className={`ti ti-mail ${styles.icon}`} aria-hidden="true" />
            Email
          </span>
        )}
      </div>

      {showsDays && (
        <p className={styles.days} data-tone={daysTone(days)}>
          {daysLeftLabel(days, row.state === 'PAUSED')}
        </p>
      )}

      {row.state === 'PENDIENTE RENOVACIÓN' && (
        <p className={styles.renewalDays}>{expiresInLabel(row.renewalDaysLeft ?? 0)}</p>
      )}

      {row.state === 'TRIGGERED' && triggered !== null && (
        <p className={styles.triggered}>{triggered}</p>
      )}

      {row.state === 'TRIGGERED' && (
        <div className={styles.actions}>
          <button
            type="button"
            className={styles.primary}
            disabled={busy}
            onClick={() => onViewResults(row)}
          >
            Ver resultados
          </button>
        </div>
      )}

      {row.state === 'PENDIENTE RENOVACIÓN' && (
        <div className={styles.renewalActions}>
          <button
            type="button"
            className={styles.primary}
            disabled={busy}
            onClick={() => onRenew(row)}
          >
            Mantener activo 30 días más
          </button>
          <button
            type="button"
            className={styles.plain}
            disabled={busy}
            onClick={() => onLetExpire(row)}
          >
            Dejar que expire
          </button>
        </div>
      )}

      <div className={styles.actions}>
        {row.state === 'ACTIVE' && (
          <button
            type="button"
            className={styles.action}
            disabled={busy}
            aria-label={`Pausar — ${row.partNumber}`}
            onClick={() => onPause(row)}
          >
            Pausar
          </button>
        )}
        {row.state === 'PAUSED' && (
          <button
            type="button"
            className={styles.action}
            disabled={busy}
            aria-label={`Reactivar — ${row.partNumber}`}
            onClick={() => onResume(row)}
          >
            Reactivar
          </button>
        )}
        {showsDays && (
          <button
            type="button"
            className={styles.action}
            disabled={busy}
            aria-label={`Editar — ${row.partNumber}`}
            onClick={() => onEdit(row)}
          >
            Editar
          </button>
        )}
        {/* Eliminar está en los cinco estados, siempre el último. */}
        <button
          type="button"
          className={`${styles.action} ${styles.danger}`}
          disabled={busy}
          aria-label={`Eliminar — ${row.partNumber}`}
          onClick={() => onDelete(row)}
        >
          Eliminar
        </button>
      </div>
    </article>
  );
}

