import type { FormEvent } from 'react';
import {
  isValidWatcherDraft,
  WATCHER_COUNTRY_OPTIONS,
  type WatcherDraft,
} from '../../lib/watchers';
import styles from './WatcherEditForm.module.css';

interface Props {
  /** La referencia de la fila que se está editando: da nombre accesible al form. */
  partNumber: string;
  /** El borrador ENTERO. El formulario no guarda nada por su cuenta. */
  draft: WatcherDraft;
  busy: boolean;
  /** Error de la última llamada a `updateWatcher`; el formulario sigue abierto. */
  error: string | null;
  onChange: (draft: WatcherDraft) => void;
  onSave: () => void;
  onCancel: () => void;
}

/**
 * SRCH-03 · Formulario `Editar watcher` (spec §4). Totalmente controlado: cada
 * cambio emite el borrador completo hacia arriba, que es quien lo posee. Los cinco
 * campos van con su etiqueta implícita (el control dentro del `<label>`) y su hint
 * DEBAJO, en el orden de la spec.
 */
export function WatcherEditForm({
  partNumber,
  draft,
  busy,
  error,
  onChange,
  onSave,
  onCancel,
}: Props) {
  function handleSubmit(event: FormEvent<HTMLFormElement>): void {
    event.preventDefault();
    onSave();
  }

  return (
    <form className={styles.form} aria-label={'Editar watcher ' + partNumber} onSubmit={handleSubmit}>
      <div className={styles.grid}>
        <div className={styles.field}>
          <label className={styles.label}>
            Referencia
            <input
              className={styles.input}
              type="text"
              value={draft.partNumber}
              placeholder="Ej: 6308-ZZ"
              onChange={(e) => onChange({ ...draft, partNumber: e.target.value })}
            />
          </label>
          <div className={styles.hint}>Código exacto del rodamiento</div>
        </div>

        <div className={styles.field}>
          <label className={styles.label}>
            Cantidad mínima
            <input
              className={styles.input}
              type="number"
              value={draft.minQuantity}
              placeholder="Ej: 100"
              onChange={(e) => onChange({ ...draft, minQuantity: e.target.value })}
            />
          </label>
          <div className={styles.hint}>Unidades mínimas para que se dispare</div>
        </div>

        <div className={styles.field}>
          <label className={styles.label}>
            Marca
            <input
              className={styles.input}
              type="text"
              value={draft.brand}
              placeholder="Cualquier marca"
              onChange={(e) => onChange({ ...draft, brand: e.target.value })}
            />
          </label>
          <div className={styles.hint}>Opcional — deja vacío para cualquier fabricante</div>
        </div>

        <div className={styles.field}>
          <label className={styles.label}>
            País
            <select
              className={styles.select}
              value={draft.country}
              onChange={(e) => onChange({ ...draft, country: e.target.value })}
            >
              <option value="">Cualquier país</option>
              {WATCHER_COUNTRY_OPTIONS.map((option) => (
                <option key={option.code} value={option.code}>
                  {option.label}
                </option>
              ))}
            </select>
          </label>
          <div className={styles.hint}>Opcional — deja vacío para cualquier origen</div>
        </div>
      </div>

      <div className={styles.field}>
        <label className={styles.checkLabel}>
          <input
            className={styles.checkbox}
            type="checkbox"
            checked={draft.emailChannel}
            onChange={(e) => onChange({ ...draft, emailChannel: e.target.checked })}
          />
          Canal email
        </label>
        <div className={styles.hint}>Recibirás también una notificación por email</div>
      </div>

      {error !== null && (
        <p className={styles.error} role="alert">
          {error}
        </p>
      )}

      <div className={styles.buttons}>
        <button type="submit" className={styles.save} disabled={!isValidWatcherDraft(draft) || busy}>
          Guardar cambios
        </button>
        <button type="button" className={styles.cancel} onClick={onCancel}>
          Cancelar
        </button>
      </div>
    </form>
  );
}

