import { useEffect, useState } from 'react';
import type { SearchCriteria } from '../../lib/search';
import { errorMessage, type MemberProfile } from '../../lib/session';
import {
  activeCounterLabel,
  counterTone,
  DEFAULT_WATCHER_FILTER,
  deleteWatcher,
  draftFromRow,
  fetchWatchers,
  filterWatchers,
  letWatcherExpire,
  renewWatcher,
  setWatcherPaused,
  updateWatcher,
  WATCHER_FILTERS,
  watcherFilterCount,
  watcherToCriteria,
  type WatcherDraft,
  type WatcherFilterKey,
  type WatcherRow,
} from '../../lib/watchers';
import { DeleteWatcherModal } from './DeleteWatcherModal';
import { WatcherCard } from './WatcherCard';
import { WatcherEditForm } from './WatcherEditForm';
import styles from './Watchers.module.css';

const EYEBROW = 'Módulo 03 · Búsqueda Conversacional';
const TITLE = 'Mis watchers';
const SUBTITLE =
  'Los watchers te avisan cuando aparece stock de una referencia que buscas. Cada watcher está activo durante 30 días y puedes renovarlo.';

/* Los dos literales del estado vacío (spec §6). Van como constantes y no como
   texto partido en varias líneas de JSX para que el texto del DOM sea exacto. */
const EMPTY_TITLE = 'Todavía no tienes ningún watcher activo.';
const EMPTY_TEXT =
  'Crea un watcher desde la búsqueda cuando no encuentres stock de una referencia — te avisaremos cuando aparezca.';

interface Props {
  /**
   * La sesión del miembro. La capa de datos ya filtra por organización vía RLS
   * (`0035`), así que la pantalla no la usa: va en la firma porque es el contrato
   * de las pantallas de miembro.
   */
  profile: MemberProfile;
  /** Inyectable para que los tests no dependan del reloj (INV-01/SRCH-01/PANEL-01). */
  now?: Date;
  /** «Ver resultados» de una tarjeta TRIGGERED: precarga SRCH-01 con sus criterios. */
  onViewResults: (criteria: SearchCriteria) => void;
}

/**
 * SRCH-03 · Gestión de Watchers. La pantalla posee TODO el estado: la lista
 * completa se pide una vez al montar y los seis chips filtran en cliente sobre
 * ella (nunca vuelven a consultar la base). Las cinco acciones y el borrado pasan
 * por la capa de datos y, si salen bien, releen la lista; si fallan, dejan el
 * mensaje donde corresponde y no tocan nada más.
 */
export function Watchers({ now, onViewResults }: Props) {
  const [rows, setRows] = useState<WatcherRow[]>([]);
  const [loaded, setLoaded] = useState(false);
  const [loadError, setLoadError] = useState<string | null>(null);

  const [filterKey, setFilterKey] = useState<WatcherFilterKey>(DEFAULT_WATCHER_FILTER);

  const [busy, setBusy] = useState(false);
  const [notice, setNotice] = useState<string | null>(null);
  const [actionError, setActionError] = useState<string | null>(null);

  const [editingId, setEditingId] = useState<string | null>(null);
  const [draft, setDraft] = useState<WatcherDraft | null>(null);
  const [editError, setEditError] = useState<string | null>(null);

  const [deleting, setDeleting] = useState<WatcherRow | null>(null);
  const [deleteError, setDeleteError] = useState<string | null>(null);

  /*
   * Una sola vez al montar: la lista COMPLETA, sin filtrar. Los chips trabajan
   * sobre este array en memoria. `now` no entra en el efecto a propósito — no se
   * consulta con él, solo se formatea (el bucle que documenta `Panel.tsx`).
   */
  useEffect(() => {
    let active = true;

    fetchWatchers()
      .then((list) => {
        if (!active) return;
        setRows(list);
        setLoaded(true);
      })
      .catch((e: unknown) => {
        if (!active) return;
        setLoadError(errorMessage(e));
        setLoaded(true);
      });

    return () => {
      active = false;
    };
  }, []);

  /** Relectura tras una acción que ha ido bien. */
  async function reload(): Promise<void> {
    const list = await fetchWatchers();
    setRows(list);
  }

  /**
   * El tronco común de las cuatro acciones de tarjeta: `busy` mientras la llamada
   * está en vuelo, relectura y aviso si sale bien, `role="alert"` de pantalla (sin
   * relectura y sin aviso) si falla.
   */
  async function runAction(action: () => Promise<void>, success: string): Promise<void> {
    setBusy(true);
    setNotice(null);
    setActionError(null);
    try {
      await action();
      await reload();
      setNotice(success);
    } catch (e: unknown) {
      setActionError(errorMessage(e));
    } finally {
      setBusy(false);
    }
  }

  function handlePause(row: WatcherRow): void {
    void runAction(() => setWatcherPaused(row.id, true), `Watcher de ${row.partNumber} pausado.`);
  }

  function handleResume(row: WatcherRow): void {
    void runAction(
      () => setWatcherPaused(row.id, false),
      `Watcher de ${row.partNumber} reactivado.`,
    );
  }

  function handleRenew(row: WatcherRow): void {
    void runAction(
      () => renewWatcher(row.id),
      `Watcher de ${row.partNumber} renovado por 30 días más.`,
    );
  }

  function handleLetExpire(row: WatcherRow): void {
    void runAction(() => letWatcherExpire(row.id), `Watcher de ${row.partNumber} expirado.`);
  }

  function handleViewResults(row: WatcherRow): void {
    onViewResults(watcherToCriteria(row));
  }

  // ── Edición inline: solo UNA tarjeta a la vez ──────────────────────────────
  const editingRow = rows.find((r) => r.id === editingId) ?? null;

  function handleEdit(row: WatcherRow): void {
    setEditingId(row.id);
    setDraft(draftFromRow(row));
    setEditError(null);
  }

  function handleCancelEdit(): void {
    setEditingId(null);
    setDraft(null);
    setEditError(null);
  }

  async function handleSaveEdit(): Promise<void> {
    if (editingRow === null || draft === null) return;
    const ref = editingRow.partNumber;
    setBusy(true);
    setEditError(null);
    setNotice(null);
    setActionError(null);
    try {
      await updateWatcher(editingRow.id, draft);
      setEditingId(null);
      setDraft(null);
      await reload();
      setNotice(`Watcher de ${ref} actualizado.`);
    } catch (e: unknown) {
      // El formulario sigue abierto con el mensaje dentro.
      setEditError(errorMessage(e));
    } finally {
      setBusy(false);
    }
  }

  // ── Borrado: nunca directo, siempre por el modal ───────────────────────────
  function handleDelete(row: WatcherRow): void {
    setDeleting(row);
    setDeleteError(null);
  }

  function handleCancelDelete(): void {
    setDeleting(null);
    setDeleteError(null);
  }

  async function handleConfirmDelete(): Promise<void> {
    if (deleting === null) return;
    const { id, partNumber } = deleting;
    setBusy(true);
    setDeleteError(null);
    setNotice(null);
    setActionError(null);
    try {
      await deleteWatcher(id);
      setDeleting(null);
      await reload();
      setNotice(`Watcher de ${partNumber} eliminado.`);
    } catch (e: unknown) {
      // El modal sigue abierto con el error dentro.
      setDeleteError(errorMessage(e));
    } finally {
      setBusy(false);
    }
  }

  const currentTime = now ?? new Date();
  const visible = filterWatchers(rows, filterKey);

  return (
    <div className={styles.screen}>
      <div className={styles.eyebrow}>{EYEBROW}</div>
      <h1 className={styles.title}>{TITLE}</h1>
      <p className={styles.sub}>{SUBTITLE}</p>

      {/* Un solo aviso a la vez: se pinta o el de la acción o el de error. */}
      {notice !== null && (
        <p className={styles.notice} role="status">
          {notice}
        </p>
      )}
      {actionError !== null && (
        <p className={styles.error} role="alert">
          {actionError}
        </p>
      )}

      {/* El contador cuenta solo ACTIVE y su tono sale de la capa de datos. */}
      <span className={styles.counter} data-testid="watcher-counter" data-tone={counterTone(rows)}>
        {activeCounterLabel(rows)}
      </span>

      {/* Seis chips, en el orden de la capa de datos. El contador de cada uno va
          en su propio `<span>`: el nombre accesible es «Etiqueta N». */}
      <div className={styles.chips}>
        {WATCHER_FILTERS.map((filter) => (
          <button
            key={filter.key}
            type="button"
            className={styles.chip}
            aria-pressed={filterKey === filter.key}
            onClick={() => setFilterKey(filter.key)}
          >
            {filter.label}{' '}
            <span className={styles.chipCount}>{watcherFilterCount(rows, filter.key)}</span>
          </button>
        ))}
      </div>

      {loadError !== null ? (
        <p className={styles.error} role="alert" data-testid="watchers-error">
          {loadError}
        </p>
      ) : !loaded ? (
        <p className={styles.loading} aria-busy="true">
          Cargando watchers…
        </p>
      ) : rows.length === 0 ? (
        <div className={styles.empty}>
          <p className={styles.emptyTitle}>{EMPTY_TITLE}</p>
          <p className={styles.emptyText}>{EMPTY_TEXT}</p>
        </div>
      ) : visible.length === 0 ? (
        <p className={styles.empty}>No hay watchers en este estado.</p>
      ) : (
        <ul className={styles.list} aria-label="Lista de watchers">
          {visible.map((row) => (
            <li key={row.id} className={styles.item}>
              <WatcherCard
                row={row}
                now={currentTime}
                busy={busy}
                onPause={handlePause}
                onResume={handleResume}
                onEdit={handleEdit}
                onDelete={handleDelete}
                onRenew={handleRenew}
                onLetExpire={handleLetExpire}
                onViewResults={handleViewResults}
              />
              {editingId === row.id && draft !== null && (
                <WatcherEditForm
                  partNumber={row.partNumber}
                  draft={draft}
                  busy={busy}
                  error={editError}
                  onChange={setDraft}
                  onSave={() => {
                    void handleSaveEdit();
                  }}
                  onCancel={handleCancelEdit}
                />
              )}
            </li>
          ))}
        </ul>
      )}

      {deleting !== null && (
        <DeleteWatcherModal
          partNumber={deleting.partNumber}
          busy={busy}
          error={deleteError}
          onConfirm={() => {
            void handleConfirmDelete();
          }}
          onCancel={handleCancelDelete}
        />
      )}
    </div>
  );
}
